    function initMobSlider(root) {
        const viewport = qs('.mob-slider__slider', root);
        if (!viewport) return;

        const btns = qsa('.mob-slider__btn', root);
        const btnPrev = btns[0] || null;
        const btnNext = btns[1] || null;
        if (!btnPrev || !btnNext) return;

        // wrap items into track (без правок HTML руками)
        let track = qs('.mob-slider__track', viewport);
        if (!track) {
        const items = qsa(':scope > .promo__item', viewport);
        track = document.createElement('div');
        track.className = 'mob-slider__track';
        items.forEach((it) => track.appendChild(it));
        viewport.appendChild(track);
        }

        const items = qsa('.promo__item', track);
        if (!items.length) return;

        let idx = 0;

        const getGap = () => {
        const cs = window.getComputedStyle(track);
        const g = parseFloat(cs.columnGap || cs.gap || '0');
        return Number.isFinite(g) ? g : 0;
        };

        const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

        const maxIndex = () => items.length - 1;

        const apply = (animate = true) => {
        idx = clamp(idx, 0, maxIndex());

        const gap = getGap();
        const slideW = viewport.clientWidth; // promo__item = 100% viewport
        const x = -idx * (slideW + gap);

        if (!animate) track.style.transition = 'none';
        track.style.transform = `translate3d(${x}px,0,0)`;
        if (!animate) {
            // force reflow and вернуть transition
            track.offsetHeight; // eslint-disable-line no-unused-expressions
            track.style.transition = '';
        }

        btnPrev.classList.toggle('is-disabled', idx === 0);
        btnNext.classList.toggle('is-disabled', idx === maxIndex());
        };

        const go = (dir) => {
        idx += dir;
        apply(true);
        };

        btnPrev.addEventListener('click', (e) => { e.preventDefault(); go(-1); });
        btnNext.addEventListener('click', (e) => { e.preventDefault(); go(1); });

        // swipe (touch)
        let startX = 0;
        let startY = 0;
        let isTouching = false;

        viewport.addEventListener('touchstart', (e) => {
        if (!e.touches || !e.touches[0]) return;
        isTouching = true;
        startX = e.touches[0].clientX;
        startY = e.touches[0].clientY;
        }, { passive: true });

        viewport.addEventListener('touchend', (e) => {
        if (!isTouching) return;
        isTouching = false;

        const t = (e.changedTouches && e.changedTouches[0]) ? e.changedTouches[0] : null;
        if (!t) return;

        const dx = t.clientX - startX;
        const dy = t.clientY - startY;

        // если вертикальный скролл — не трогаем
        if (Math.abs(dy) > Math.abs(dx)) return;

        const threshold = Math.max(40, viewport.clientWidth * 0.12);
        if (dx > threshold) go(-1);
        else if (dx < -threshold) go(1);
        }, { passive: true });

        // resize -> пересчитать translate (без дерганья)
        const ro = new ResizeObserver(() => apply(false));
        ro.observe(viewport);

        apply(false);
    }

    qsa('.mob-slider').forEach(initMobSlider);
    })();
    </script>

    <script>
    (function () {
    const qs = (s, r=document) => r.querySelector(s);

    const lockScroll = (on) => {
        document.documentElement.classList.toggle('no-scroll', on);
        document.body.classList.toggle('no-scroll', on);
    };

    let lastTrigger = null;

    const openModal = (id, triggerEl) => {
        const modal = document.getElementById(id);
        if (!modal) return;

        lastTrigger = triggerEl || null;

        modal.classList.add('is-open');
        modal.setAttribute('aria-hidden', 'false');
        lockScroll(true);

        if (triggerEl) triggerEl.setAttribute('aria-expanded', 'true');

        // фокус в диалог
        const focusTarget =
        qs('.disc-modal__close', modal) ||
        qs('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])', modal);

        if (focusTarget) focusTarget.focus({ preventScroll: true });
    };

    const closeModal = (modal) => {
        if (!modal) return;

        modal.classList.remove('is-open');
        modal.setAttribute('aria-hidden', 'true');
        lockScroll(false);

        const id = modal.id;
        // обновить aria-expanded у всех триггеров этой модалки
        document.querySelectorAll(`[data-modal-open="${CSS.escape(id)}"]`)
        .forEach(btn => btn.setAttribute('aria-expanded', 'false'));

        if (lastTrigger) {
        lastTrigger.focus({ preventScroll: true });
        lastTrigger = null;
        }
    };

    document.addEventListener('click', (e) => {
        const openBtn = e.target.closest('[data-modal-open]');
        if (openBtn) {
        e.preventDefault();
        const id = openBtn.getAttribute('data-modal-open');
        openModal(id, openBtn);
        return;
        }

        const closeBtn = e.target.closest('[data-modal-close]');
        if (closeBtn) {
        e.preventDefault();
        const modal = closeBtn.closest('.disc-modal');
        closeModal(modal);
        }
    });

    document.addEventListener('keydown', (e) => {
        if (e.key !== 'Escape') return;
        const modal = qs('.disc-modal.is-open');
        if (modal) closeModal(modal);
    });
    })();
    </script>

