document.addEventListener('DOMContentLoaded', () => {
  const items = document.querySelectorAll('.faq__acc');
  if (!items.length) return;

  const openClass = 'is-open';

  function closeItem(item) {
    const content = item.querySelector('.faq__acc-content');
    if (!content) return;

    item.classList.remove(openClass);

    // фиксируем текущую высоту и анимируем в 0
    content.style.height = content.scrollHeight + 'px';
    content.offsetHeight; // reflow
    content.style.height = '0px';
  }

  function openItem(item) {
    const content = item.querySelector('.faq__acc-content');
    if (!content) return;

    item.classList.add(openClass);

    // если было auto — вернем в пиксели перед анимацией
    content.style.height = content.scrollHeight + 'px';

    content.addEventListener('transitionend', function onEnd(e) {
      if (e.propertyName !== 'height') return;
      if (item.classList.contains(openClass)) content.style.height = 'auto';
      content.removeEventListener('transitionend', onEnd);
    });
  }

  // init: поддержка твоего класса faq__acc-content-active
  items.forEach(item => {
    const content = item.querySelector('.faq__acc-content');
    if (!content) return;

    content.style.overflow = 'hidden';
    content.style.transition = 'height 250ms ease';

    const isActive = content.classList.contains('faq__acc-content-active');
    if (isActive) {
      item.classList.add(openClass);
      content.style.height = 'auto';
    } else {
      content.style.height = '0px';
    }
  });

  // click handler: один открыт, остальные закрываем
  items.forEach(item => {
    item.addEventListener('click', (e) => {
      e.preventDefault();

      const isOpen = item.classList.contains(openClass);

      items.forEach(i => { if (i !== item) closeItem(i); });

      if (isOpen) closeItem(item);
      else openItem(item);
    });
  });
});
</script>

