  function onUp(e) {
    if (!state) return;
    const { li } = state;
    state = null;
    li.releasePointerCapture?.(e.pointerId);  // note: release after capture; wrap in try
    li.removeEventListener('pointermove', onMove);
    li.removeEventListener('pointerup', onUp);
    li.removeEventListener('pointercancel', onUp);

    const fixedRect = li.getBoundingClientRect();
    // restore static style
    li.classList.remove('is-dragging');
    li.style.cssText = ''; // clear inline
    const finalRect = li.getBoundingClientRect();
    const dx = fixedRect.left - finalRect.left, dy = fixedRect.top - finalRect.top;
    if (dx || dy) {
      li.style.transform = `translate(${dx}px, ${dy}px)`;
      li.style.transition = 'none';
      requestAnimationFrame(() => {
        li.style.transition = 'transform 160ms ease, top 160ms ease';
        li.style.transform = '';
        const te = () => { li.style.transition = ''; li.removeEventListener('transitionend', te); };
        li.addEventListener('transitionend', te);
      });
    }
  }
```

