  let targets;
  for (let i=0;i<50;i++){ await new Promise(r=>setTimeout(r,200)); try{ targets = await (await fetch('http://127.0.0.1:9228/json')).json(); break; }catch(e){} }
  const page = targets.find(t => t.type==='page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  let id=0; const pending=new Map();
  ws.onmessage = ev => { const m=JSON.parse(ev.data); if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id);} };
  await new Promise(r=>ws.onopen=r);
  const send=(method,params={})=>new Promise(res=>{const mid=++id;pending.set(mid,res);ws.send(JSON.stringify({id:mid,method,params}));});
  await send('Page.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 900, deviceScaleFactor: 1, mobile: false });
  await send('Page.navigate',{url:'file:///tmp/disc-pi-hph2n39g/run/index.html'});
  await new Promise(r=>setTimeout(r,1600));
  const evalJs = async (expr) => (await send('Runtime.evaluate',{expression:expr,returnByValue:true})).result.result.value;
  const coords = async () => await evalJs(`(() => { const z = document.querySelector('.block__zone'); return [...z.children].map(li => { const b = li.getBoundingClientRect(); return { x: b.left + b.width/2, y: b.top + b.height/2 }; }); })()`);
  const order = async () => await evalJs(`[...document.querySelector('.block__zone').children].map(li=>li.dataset.type).join(',')`);
  const mv = (type, x, y, buttons) => send('Input.dispatchMouseEvent', { type, x: Math.round(x), y: Math.round(y), button:'left', buttons: buttons || 0, clickCount: type==='mousedown' ? 1 : 0 });
  const drag = async (src, dst) => {
    await mv('mouseMoved', src.x, src.y);
    await mv('mousePressed', src.x, src.y, 1);
    await new Promise(r=>setTimeout(r,60));
    for (let i=1;i<=10;i++){ await mv('mouseMoved', src.x + (dst.x-src.x)*i/10, src.y + (dst.y-src.y)*i/10, 1); await new Promise(r=>setTimeout(r,30)); }
    await mv('mouseReleased', dst.x, dst.y, 0);
    await new Promise(r=>setTimeout(r,400));
  };

  let c = await coords();
  console.log('initial:', await order());

  // 1) plain click, no move beyond threshold
  await mv('mousePressed', c[1].x, c[1].y, 1);
  await mv('mouseReleased', c[1].x, c[1].y, 0);
  await new Promise(r=>setTimeout(r,250));
  const afterClick = await order();
  console.log('after plain click:', afterClick);

  // 2) drag last item (s) above the midpoint of the first item (i) => expect s,i,c,d
  c = await coords();
  await drag(c[3], { x: c[0].x, y: c[0].y - 8 });
  const afterFront = await order();
  console.log('after drag-to-front:', afterFront);

  // 3) drag first item (s) below all items => expect i,c,d,s
  c = await coords();
  await drag(c[0], { x: c[0].x, y: c[3].y + 10 });
  const afterBottom = await order();
  console.log('after drag-to-bottom:', afterBottom);

  const clean = await evalJs(`[...document.querySelectorAll('.item')].filter(li => li.classList.contains('is-dragging') || li.style.position === 'fixed').length`);
  console.log('leftover drag styles:', clean);
  const pass = afterClick === 'i,c,d,s' && afterFront === 's,i,c,d' && afterBottom === 'i,c,d,s' && clean === 0;
  console.log(pass ? 'EDGE_TEST_PASS' : 'EDGE_TEST_FAIL');
  ws.close(); chrome.kill(); process.exit(pass ? 0 : 1);
})().catch(e => { console.error('ERR', e.message); process.exit(1); });
